"""Semantic version ordering."""


def _pre_ids(pre):
    """Split a pre-release string into comparable identifiers.

    Numeric identifiers sort numerically and before alphanumeric ones.
    """
    out = []
    for ident in pre.split("."):
        if ident.isdigit():
            out.append((0, int(ident), ""))
        else:
            out.append((1, 0, ident))
    return tuple(out)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    core, _, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if pre:
        # 0 < 1, so any pre-release sorts before the release with the same core.
        return nums + (0, _pre_ids(pre))
    return nums + (1, ())

"""Caret ranges like ^1.2.3."""


def _parse(text):
    parts = [int(x) for x in text.split(".")]
    return tuple(parts + [0] * (3 - len(parts)))


def satisfies(version, rng):
    """^X.Y.Z allows >= X.Y.Z and below the next bump of the first non-zero part.

    ^1.2.3 -> >=1.2.3 <2.0.0
    ^0.2.3 -> >=0.2.3 <0.3.0
    ^0.0.3 -> >=0.0.3 <0.0.4
    """
    base = _parse(rng.lstrip("^"))
    v = _parse(version)
    if v < base:
        return False
    x, y, _ = base
    if x > 0:
        return v[0] == x
    if y > 0:
        return v[0] == 0 and v[1] == y
    return v[:2] == (0, 0) and v[2] == base[2]

